"""Read a legacy fit generated by the actual immutable public 1.1.0 wheel."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path

import numpy as np

from kernelgecp import FermionicFit

DATA = Path(__file__).parent / "data"


def test_actual_public_110_archive_loads_and_migrates_without_changing_predictions(
    tmp_path: Path,
) -> None:
    archive = DATA / "fermionic_fit_v1_1_0.npz"
    provenance = json.loads((DATA / "fermionic_fit_v1_1_0.json").read_text())
    assert (
        hashlib.sha256(archive.read_bytes()).hexdigest() == provenance["archive_sha256"]
    )
    assert provenance["generator_version"] == "1.1.0"
    assert provenance["installed_module_outside_checkout"] is True
    with np.load(archive, allow_pickle=False) as payload:
        metadata = json.loads(payload["__metadata__"].tobytes())
    assert metadata["version"] == 1
    fit = FermionicFit.load(archive)
    assert fit.observation_domain == "tau"
    assert fit.basis.rank == provenance["rank"]
    energies = np.asarray(provenance["energies"])
    residues = np.asarray(provenance["residues_real"]) + 1j * np.asarray(
        provenance["residues_imag"]
    )
    beta = provenance["beta"]
    tau = (np.arange(37) + 0.37) * beta / 37
    indices = np.arange(-10, 10)
    expected_tau = -np.einsum(
        "te,eij->tij",
        np.exp(-tau[:, None] * energies) / (1 + np.exp(-beta * energies)),
        residues,
    )
    expected_iw = np.einsum(
        "ne,eij->nij",
        1 / (1j * (2 * indices[:, None] + 1) * np.pi / beta - energies),
        residues,
    )
    np.testing.assert_allclose(fit.evaluate_tau(tau), expected_tau, rtol=0, atol=1e-8)
    np.testing.assert_allclose(
        fit.evaluate_matsubara(indices), expected_iw, rtol=0, atol=1e-8
    )
    migrated_path = tmp_path / "migrated.npz"
    fit.save(migrated_path)
    with np.load(migrated_path, allow_pickle=False) as payload:
        migrated_metadata = json.loads(payload["__metadata__"].tobytes())
    assert migrated_metadata["version"] == 2
    migrated = FermionicFit.load(migrated_path)
    assert migrated.observation_domain == "tau"
    np.testing.assert_array_equal(migrated.coefficients, fit.coefficients)
    np.testing.assert_array_equal(migrated.evaluate_tau(tau), fit.evaluate_tau(tau))
    np.testing.assert_array_equal(
        migrated.evaluate_matsubara(indices), fit.evaluate_matsubara(indices)
    )
